use nocturne_native::NativeScene;
#[test]fn original_observatory_overlay(){let mut s=NativeScene::new(2030).unwrap();for line in include_str!("../../../tests/fixtures/original-observatory-overlay/setup.ndjson").lines(){s.command(line).unwrap();}s.command(r#"{"op":"observatory-overlay","kind":"dag","flatNavigation":true}"#).unwrap();let info=s.infoComplete().unwrap();assert!(info.contains(r#""observatoryOverlay":{"enabled":true,"kind":"dag","flatNavigation":true"#));let before=s.snapshot().unwrap();assert!(s.command(r#"{"op":"observatory-overlay","textHueSpeed":91}"#).is_err());assert_eq!(s.snapshot().unwrap(),before);s.command(r#"{"op":"observatory-overlay","enabled":false}"#).unwrap();}
